{
  "name": "惠普 85645A 射频信号发生器",
  "name_en": "HP 85645A RF Signal Generator",
  "manufacturer": "Hewlett-Packard",
  "description": "这是一台台式射频信号发生器，可输出频率和幅度可调的电信号，并支持输出开关与输出耦合设置。它常用于电子与射频实验中的激励源、器件表征、测试校准以及系统响应测量。",
  "description_en": "This is a benchtop RF signal generator that provides electrical signals with adjustable frequency and amplitude, with configurable output enable and output coupling. It is commonly used as a stimulus source in electronics and RF labs for device characterization, test calibration, and response measurements.",
  "actions": [
    {
      "action_name": "auto-OUTPut_COUPling",
      "description": "获取或设置输出耦合方式",
      "description_en": "Get or set the output coupling"
    },
    {
      "action_name": "auto-frequency",
      "description": "获取或设置输出频率",
      "description_en": "Get or set the output frequency"
    },
    {
      "action_name": "auto-amplitude",
      "description": "获取或设置输出幅度",
      "description_en": "Get or set the output amplitude"
    },
    {
      "action_name": "auto-output",
      "description": "获取或设置输出开关状态",
      "description_en": "Get or set the output on/off state"
    }
  ],
  "tag_hints": [
    "RF signal generator",
    "signal source",
    "frequency control",
    "amplitude control",
    "electronic test equipment",
    "instrument calibration"
  ]
}

